import test from'node:test';import assert from'node:assert/strict';import{ComputationalGrammarCoder,computationalGrammarCoderAutomaton}from'../src/index.mjs';
test('source-grounded function words receive unique grammar codes',()=>{const c=new ComputationalGrammarCoder(),r=c.code('The vehicle is entering.');assert.equal(r.words[0].codes[0],'ART');assert.equal(r.words[2].codes[0],'VERB_IS');assert.equal(r.words[3].codes[0],'/ING/');assert.equal(r.words[4].codes[0],'.TYPE');});
test('suffix and numeral tests reduce form-class possibilities',()=>{const c=new ComputationalGrammarCoder();assert.deepEqual(c.candidates('nationality').codes,['NOUN']);assert.deepEqual(c.candidates('42').codes,['ADJ']);assert.deepEqual(c.candidates('quickly').codes,['ADV']);});
test('unknown words remain explicit ambiguous choices rather than guessed',()=>{const r=new ComputationalGrammarCoder().code('glorp');assert.deepEqual(r.words[0].codes,['ADJ','ADV','NOUN','VERB']);assert.deepEqual(r.ambiguous,['glorp']);});
test('computational grammar coder is a standalone addressed Automaton',async()=>{const tool=computationalGrammarCoderAutomaton(),result=await tool.call({text:'This is clear.'});assert.equal(tool.metadata.source,'Klein & Simmons 1963');assert.equal(result.words[0].codes[0],'PN_DEM');});
